/* eslint-disable max-len, id-length */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var dlansb = require( './../lib/ndarray.js' );


// FIXTURES //

var COLUMN_MAJOR_UPPER = require( './fixtures/column_major_upper.json' );
var COLUMN_MAJOR_LOWER = require( './fixtures/column_major_lower.json' );
var COLUMN_MAJOR_UPPER_OFFSET = require( './fixtures/column_major_upper_offset.json' );
var COLUMN_MAJOR_UPPER_LARGE_STRIDES = require( './fixtures/column_major_upper_large_strides.json' );
var COLUMN_MAJOR_UPPER_NEGATIVE_STRIDES = require( './fixtures/column_major_upper_negative_strides.json' );
var COLUMN_MAJOR_UPPER_MIXED_STRIDES = require( './fixtures/column_major_upper_mixed_strides.json' );
var COLUMN_MAJOR_UPPER_K0 = require( './fixtures/column_major_upper_k0.json' );
var COLUMN_MAJOR_LOWER_K0 = require( './fixtures/column_major_lower_k0.json' );
var ROW_MAJOR_UPPER = require( './fixtures/row_major_upper.json' );
var ROW_MAJOR_LOWER = require( './fixtures/row_major_lower.json' );
var ROW_MAJOR_LOWER_OFFSET = require( './fixtures/row_major_lower_offset.json' );
var ROW_MAJOR_LOWER_LARGE_STRIDES = require( './fixtures/row_major_lower_large_strides.json' );
var ROW_MAJOR_LOWER_NEGATIVE_STRIDES = require( './fixtures/row_major_lower_negative_strides.json' );
var ROW_MAJOR_LOWER_MIXED_STRIDES = require( './fixtures/row_major_lower_mixed_strides.json' );


// FUNCTIONS //

/**
* Asserts that the function computes the expected value for each supported norm.
*
* @private
* @param {Object} t - test object
* @param {Object} data - fixture data
*/
function isExpected( t, data ) {
	var work = new Float64Array( data.N );
	t.strictEqual( dlansb( 'max', data.uplo, data.N, data.K, new Float64Array( data.AB ), data.strideAB1, data.strideAB2, data.offsetAB, work, 1, 0 ), data.expectedMax, 'returns expected value' );
	t.strictEqual( dlansb( 'one', data.uplo, data.N, data.K, new Float64Array( data.AB ), data.strideAB1, data.strideAB2, data.offsetAB, work, 1, 0 ), data.expectedOne, 'returns expected value' );
	t.strictEqual( dlansb( 'inf', data.uplo, data.N, data.K, new Float64Array( data.AB ), data.strideAB1, data.strideAB2, data.offsetAB, work, 1, 0 ), data.expectedInf, 'returns expected value' );
	t.strictEqual( dlansb( 'fro', data.uplo, data.N, data.K, new Float64Array( data.AB ), data.strideAB1, data.strideAB2, data.offsetAB, work, 1, 0 ), data.expectedFro, 'returns expected value' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlansb, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 11', function test( t ) {
	t.strictEqual( dlansb.length, 11, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid norm', function test( t ) {
	var values;
	var work;
	var AB;
	var i;

	AB = new Float64Array( COLUMN_MAJOR_UPPER.AB );
	work = new Float64Array( COLUMN_MAJOR_UPPER.N );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlansb( value, 'upper', 4, 2, AB, 1, 3, 0, work, 1, 0 );
		};
	}
});

tape( 'the function throws an error if provided a second argument which is not a valid matrix triangle', function test( t ) {
	var values;
	var work;
	var AB;
	var i;

	AB = new Float64Array( COLUMN_MAJOR_UPPER.AB );
	work = new Float64Array( COLUMN_MAJOR_UPPER.N );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlansb( 'max', value, 4, 2, AB, 1, 3, 0, work, 1, 0 );
		};
	}
});

tape( 'the function computes the norms of a symmetric band matrix (column-major, upper)', function test( t ) {
	isExpected( t, COLUMN_MAJOR_UPPER );
	t.end();
});

tape( 'the function computes the norms of a symmetric band matrix (column-major, lower)', function test( t ) {
	isExpected( t, COLUMN_MAJOR_LOWER );
	t.end();
});

tape( 'the function computes the norms of a symmetric band matrix (row-major, upper)', function test( t ) {
	isExpected( t, ROW_MAJOR_UPPER );
	t.end();
});

tape( 'the function computes the norms of a symmetric band matrix (row-major, lower)', function test( t ) {
	isExpected( t, ROW_MAJOR_LOWER );
	t.end();
});

tape( 'the function computes the norms of a diagonal matrix (K=0, upper)', function test( t ) {
	isExpected( t, COLUMN_MAJOR_UPPER_K0 );
	t.end();
});

tape( 'the function computes the norms of a diagonal matrix (K=0, lower)', function test( t ) {
	isExpected( t, COLUMN_MAJOR_LOWER_K0 );
	t.end();
});

tape( 'the function supports an offset for the matrix (column-major, upper)', function test( t ) {
	isExpected( t, COLUMN_MAJOR_UPPER_OFFSET );
	t.end();
});

tape( 'the function supports an offset for the matrix (row-major, lower)', function test( t ) {
	isExpected( t, ROW_MAJOR_LOWER_OFFSET );
	t.end();
});

tape( 'the function supports large strides (column-major, upper)', function test( t ) {
	isExpected( t, COLUMN_MAJOR_UPPER_LARGE_STRIDES );
	t.end();
});

tape( 'the function supports large strides (row-major, lower)', function test( t ) {
	isExpected( t, ROW_MAJOR_LOWER_LARGE_STRIDES );
	t.end();
});

tape( 'the function supports negative strides (column-major, upper)', function test( t ) {
	isExpected( t, COLUMN_MAJOR_UPPER_NEGATIVE_STRIDES );
	t.end();
});

tape( 'the function supports negative strides (row-major, lower)', function test( t ) {
	isExpected( t, ROW_MAJOR_LOWER_NEGATIVE_STRIDES );
	t.end();
});

tape( 'the function supports mixed strides (column-major, upper)', function test( t ) {
	isExpected( t, COLUMN_MAJOR_UPPER_MIXED_STRIDES );
	t.end();
});

tape( 'the function supports mixed strides (row-major, lower)', function test( t ) {
	isExpected( t, ROW_MAJOR_LOWER_MIXED_STRIDES );
	t.end();
});

tape( 'the function supports a stride and offset for the workspace array (infinity norm)', function test( t ) {
	var data;
	var work;
	var got;
	var AB;

	data = COLUMN_MAJOR_UPPER;
	AB = new Float64Array( data.AB );

	// Workspace with a stride of 2 and an offset of 1:
	work = new Float64Array( ( data.N*2 )+1 );

	got = dlansb( 'inf', data.uplo, data.N, data.K, AB, data.strideAB1, data.strideAB2, data.offsetAB, work, 2, 1 );
	t.strictEqual( got, data.expectedInf, 'returns expected value' );
	t.end();
});

tape( 'the function supports a stride and offset for the workspace array (one norm, lower)', function test( t ) {
	var data;
	var work;
	var got;
	var AB;

	data = COLUMN_MAJOR_LOWER;
	AB = new Float64Array( data.AB );

	// Workspace with a stride of 3 and an offset of 2:
	work = new Float64Array( ( data.N*3 )+2 );

	got = dlansb( 'one', data.uplo, data.N, data.K, AB, data.strideAB1, data.strideAB2, data.offsetAB, work, 3, 2 );
	t.strictEqual( got, data.expectedOne, 'returns expected value' );
	t.end();
});

tape( 'the function supports a negative stride for the workspace array', function test( t ) {
	var data;
	var work;
	var got;
	var AB;

	data = COLUMN_MAJOR_UPPER;
	AB = new Float64Array( data.AB );
	work = new Float64Array( data.N );

	got = dlansb( 'one', data.uplo, data.N, data.K, AB, data.strideAB1, data.strideAB2, data.offsetAB, work, -1, data.N-1 );
	t.strictEqual( got, data.expectedOne, 'returns expected value' );

	data = COLUMN_MAJOR_LOWER;
	AB = new Float64Array( data.AB );
	work = new Float64Array( data.N );

	got = dlansb( 'inf', data.uplo, data.N, data.K, AB, data.strideAB1, data.strideAB2, data.offsetAB, work, -1, data.N-1 );
	t.strictEqual( got, data.expectedInf, 'returns expected value' );
	t.end();
});

tape( 'the function avoids overflow and underflow when computing the Frobenius norm', function test( t ) {
	var work;
	var AB;

	work = new Float64Array( 2 );

	// Upper triangular band storage (K=1) of a 2x2 symmetric band matrix in which every element equals `1.0e300`:
	AB = new Float64Array( [ 0.0, 1.0e300, 1.0e300, 1.0e300 ] );

	t.strictEqual( dlansb( 'fro', 'upper', 2, 1, AB, 1, 2, 0, work, 1, 0 ), 2.0e300, 'returns expected value' );

	// Lower triangular band storage (K=1) of a 2x2 symmetric band matrix in which every element equals `1.0e-300`:
	AB = new Float64Array( [ 1.0e-300, 1.0e-300, 1.0e-300, 0.0 ] );

	t.strictEqual( dlansb( 'fro', 'lower', 2, 1, AB, 1, 2, 0, work, 1, 0 ), 2.0e-300, 'returns expected value' );
	t.end();
});

tape( 'the function does not modify the input matrix', function test( t ) {
	var expected;
	var data;
	var work;
	var AB;

	data = COLUMN_MAJOR_UPPER_NEGATIVE_STRIDES;
	AB = new Float64Array( data.AB );
	expected = new Float64Array( data.AB );
	work = new Float64Array( data.N );

	dlansb( 'max', data.uplo, data.N, data.K, AB, data.strideAB1, data.strideAB2, data.offsetAB, work, 1, 0 );
	dlansb( 'one', data.uplo, data.N, data.K, AB, data.strideAB1, data.strideAB2, data.offsetAB, work, 1, 0 );
	dlansb( 'inf', data.uplo, data.N, data.K, AB, data.strideAB1, data.strideAB2, data.offsetAB, work, 1, 0 );
	dlansb( 'fro', data.uplo, data.N, data.K, AB, data.strideAB1, data.strideAB2, data.offsetAB, work, 1, 0 );

	t.deepEqual( AB, expected, 'returns expected value' );
	t.end();
});

tape( 'the function propagates `NaN` values when a referenced element is `NaN`', function test( t ) {
	var work;
	var AB;

	AB = new Float64Array( [ 0.0, 0.0, 2.0, 0.0, -1.0, NaN, 3.0, 5.0, -6.0, -2.0, 1.0, 8.0 ] );
	work = new Float64Array( 4 );

	t.strictEqual( isnan( dlansb( 'max', 'upper', 4, 2, AB, 1, 3, 0, work, 1, 0 ) ), true, 'returns expected value' );
	t.strictEqual( isnan( dlansb( 'one', 'upper', 4, 2, AB, 1, 3, 0, work, 1, 0 ) ), true, 'returns expected value' );
	t.strictEqual( isnan( dlansb( 'inf', 'upper', 4, 2, AB, 1, 3, 0, work, 1, 0 ) ), true, 'returns expected value' );
	t.strictEqual( isnan( dlansb( 'fro', 'upper', 4, 2, AB, 1, 3, 0, work, 1, 0 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0` if provided an `N` of `0`', function test( t ) {
	var work;
	var AB;

	AB = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	work = new Float64Array( 4 );

	t.strictEqual( dlansb( 'max', 'upper', 0, 1, AB, 1, 2, 0, work, 1, 0 ), 0.0, 'returns expected value' );
	t.strictEqual( dlansb( 'one', 'upper', 0, 1, AB, 1, 2, 0, work, 1, 0 ), 0.0, 'returns expected value' );
	t.strictEqual( dlansb( 'inf', 'lower', 0, 1, AB, 1, 2, 0, work, 1, 0 ), 0.0, 'returns expected value' );
	t.strictEqual( dlansb( 'fro', 'lower', 0, 1, AB, 1, 2, 0, work, 1, 0 ), 0.0, 'returns expected value' );
	t.end();
});
